		String project_path;
		String project_name = "Untitled Project";

		ViewMode view_mode = VIEW_2D;
		FocusField focus_field = FOCUS_NONE;

		bool playing = false;
		bool launched_directly_to_play = false;
		double play_time = 0.0;
		double fps_accum = 0.0;
		int fps_frames = 0;
